import java.util.LinkedHashMap;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        Map<String, Integer> stok = new LinkedHashMap<String, Integer>();
        stok.put("Apel", 10);
        stok.put("Jeruk", 5);
        stok.put("Apel", 12);

        System.out.println(stok);
        System.out.println(stok.size());
        System.out.println(stok.get("Jeruk"));
        System.out.println(stok.get("Durian"));
        System.out.println(stok.containsKey("Apel"));
        System.out.println(stok.getOrDefault("Durian", 0));
    }
}

