import java.util.LinkedHashMap;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        Map<String, Integer> nilai = new LinkedHashMap<String, Integer>();
        nilai.put("Budi", 80);
        nilai.put("Sari", 95);
        System.out.println(nilai.get("Sari"));
        System.out.println(nilai.getOrDefault("Andi", 0));
    }
}

